arguments.command:
python3 -c "
import json
with open('/app/resources/treasury_bulletin_1947_02.json', 'r') as f:
    data = json.load(f)

# Search for 1938 data
def search(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if '1938' in str(k):
                print(f'{path}.{k}: {v}')
            search(v, f'{path}.{k}')
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            if '1938' in str(item):
                print(f'{path}[{i}]: {item}')
            search(item, f'{path}[{i}]')

search(data)
"

