import json

# Load the JSON and look at all pages to see if there's any 1938 yield data
with open('/app/resources/treasury_bulletin_1947_02.json', 'r') as f:
    data = json.load(f)

# Search for any table containing both "1938" and "yield" or "bond"
def search_for_1938_yields(obj, path='', depth=0):
    if depth > 5:
        return
    if isinstance(obj, dict):
        for k, v in obj.items():
            new_path = f'{path}.{k}'
            if isinstance(v, str) and '1938' in v:
                # Check if it also has yield-related content
                if any(x in v.lower() for x in ['yield', 'bond', 'percent', 'annum']):
                    print(f"Found at {new_path}: {v[:200]}")
            search_for_1938_yields(v, new_path, depth+1)
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            search_for_1938_yields(item, f'{path}[{i}]', depth+1)

search_for_1938_yields(data)
