# Final comprehensive search for 1937 and 1938 in ALL available data
import os
import re

for filename in os.listdir('/app/resources'):
    if filename.endswith('.txt') or filename.endswith('.json'):
        path = f'/app/resources/{filename}'
        try:
            with open(path, 'r', encoding='utf-8') as f:
                content = f.read()
        except:
            try:
                with open(path, 'r', encoding='latin-1') as f:
                    content = f.read()
            except:
                continue

        # Search for any month-year pattern with 1938
        patterns_1938 = re.findall(r'1938[- ](Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)', content)
        patterns_1937 = re.findall(r'1937[- ](Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)', content)

        if patterns_1938 or patterns_1937:
            print(f"\n{filename}:")
            if patterns_1938:
                print(f"  1938 months: {patterns_1938}")
            if patterns_1937:
                print(f"  1937 months: {patterns_1937}")
